#!/usr/bin/env bash
# Documentation : droit à l'image (des droits plus récents, ou une archive) ; plages recalées.
# Prérequis : apply-fix-droits-image.sh et apply-docs-qualite.sh. Aucune migration.
# Usage (racine du repo) : bash apply-docs-droits-image.sh
set -euo pipefail
cd "$(dirname "$0")"
[ -f pnpm-workspace.yaml ] || { echo "À lancer à la racine du repo."; exit 1; }

if git show HEAD:"apps/web/content/docs/dev/legal/droit-a-l-image.mdx" 2>/dev/null | grep -qF "les droits ne changent que si des droits plus récents sont enregistrés"; then echo "Déjà appliqué (commité)."; exit 0; fi
grep -qF "byEffectiveDesc" "packages/backend/src/modules/imageConsent/router.ts" 2>/dev/null || { echo "❌ lancer d'abord apply-fix-droits-image.sh"; exit 1; }
grep -qF "Les gardes maison" "apps/web/content/docs/dev/qualite/les-gardes-maison.mdx" 2>/dev/null || { echo "❌ lancer d'abord apply-docs-qualite.sh"; exit 1; }
MODIFIED=("apps/web/content/docs/dev/api/fabriquer-une-procedure.mdx" "apps/web/content/docs/dev/api/gerer-les-erreurs.mdx" "apps/web/content/docs/dev/api/maitriser-la-sortie.mdx" "apps/web/content/docs/dev/api/proteger-une-procedure.mdx" "apps/web/content/docs/dev/api/valider-l-entree.mdx" "apps/web/content/docs/dev/auth/la-session-dans-le-backend.mdx" "apps/web/content/docs/dev/contenu/un-contenu-ecrit-par-un-membre.mdx" "apps/web/content/docs/dev/legal/consentement-en-ligne.mdx" "apps/web/content/docs/dev/legal/droit-a-l-image.mdx" "apps/web/content/docs/dev/membres/profil-et-premiere-connexion.mdx")
EXPECT=("e37860c80f91:apps/web/content/docs/dev/api/fabriquer-une-procedure.mdx" "457f7d217462:apps/web/content/docs/dev/api/gerer-les-erreurs.mdx" "297220f7180f:apps/web/content/docs/dev/api/maitriser-la-sortie.mdx" "fd79e2451551:apps/web/content/docs/dev/api/proteger-une-procedure.mdx" "77c815e43e70:apps/web/content/docs/dev/api/valider-l-entree.mdx" "4ea57f63e9fe:apps/web/content/docs/dev/auth/la-session-dans-le-backend.mdx" "2bc6e394c1d7:apps/web/content/docs/dev/contenu/un-contenu-ecrit-par-un-membre.mdx" "aed29501cf96:apps/web/content/docs/dev/legal/consentement-en-ligne.mdx" "c5037db95c4b:apps/web/content/docs/dev/legal/droit-a-l-image.mdx" "a5f73d1b2f3f:apps/web/content/docs/dev/membres/profil-et-premiere-connexion.mdx")
DIFF=0; for e in "${EXPECT[@]}"; do h=${e%%:*}; f=${e#*:}; c=$(git rev-parse "HEAD:$f" 2>/dev/null | cut -c1-12); if [ "$c" != "$h" ]; then [ $DIFF = 0 ] && echo "❌ ces fichiers ne sont pas dans l'état attendu (rien n'a été touché) :"; echo "   $f"; DIFF=1; fi; done; [ $DIFF = 0 ] || exit 1
CREATED=()
restore(){ git checkout -q -- "${MODIFIED[@]}" 2>/dev/null || true; rm -f "${CREATED[@]}"; echo "  ↩ fichiers restaurés"; }
if grep -qF "les droits ne changent que si des droits plus récents sont enregistrés" "apps/web/content/docs/dev/legal/droit-a-l-image.mdx" 2>/dev/null; then echo "  restes d'un essai précédent non commité → nettoyage"; restore; fi
if ! git diff --quiet HEAD -- "${MODIFIED[@]}" 2>/dev/null; then echo "❌ modifications non commitées dans des fichiers que ce script modifie (rien n'a été touché) :"; git diff --name-only HEAD -- "${MODIFIED[@]}" | head -5; exit 1; fi
trap 'restore' ERR


python3 - <<'PY'
import base64
spec_skip_done = False
def sub(path, old, new):
    old, new = base64.b64decode(old).decode(), base64.b64decode(new).decode()
    s = open(path, encoding="utf-8").read()
    if s.count(old) == 0 and s.count(new) == 1 and spec_skip_done: return  # déjà fait par un script précédent
    assert s.count(old) == 1, (path, old[:80], s.count(old))
    open(path, "w", encoding="utf-8").write(s.replace(old, new))
